python3 -c "
import json
with open('/Users/bymyway/.openclaw/agents/main/sessions/dce0dca4-f1eb-4432-8495-0f4954a39020.jsonl') as f:
    lines = f.readlines()
for l in lines:
    obj = json.loads(l)
    if obj.get('type') == 'message':
        m = obj['message']
        role = m.get('role')
        content = m.get('content')
        if isinstance(content, str):
            print(f'--- {role} ---')
            print(content[:1500])
        elif isinstance(content, list):
            for c in content:
                if c.get('type') == 'text':
                    print(f'--- {role} (text) ---')
                    print(c['text'][:1500])
"

